/* Sosyal Bilgiler 7 — 2. Öğrenme Alanı: Evimiz Dünya (1. kitap, s. 56–83) */
FEN.unit(2,{name:'Evimiz Dünya',game:'Küresel Kaşifler',icon:'🌍',hue:'#3bb7ff',book:1,
  pages:'s. 56–83',topics:'Küreselleşmenin insan ve toplum hayatına etkisi; bölgesel ve küresel sorunların çözümünde ülkemizin rolü'});

FEN.mis({
  u2_tekyon:{m:'Tek Yüzlü Gören',c:'#ff8a3d',t:'Küreselleşmeyi yalnızca iyi ya da yalnızca kötü bir süreç sanıyor.',s:'Küreselleşmenin hem olumlu hem olumsuz etkileri vardır.',d:'Kitap her alanda iki yüzü birlikte verir: hızlı ulaşım ve yeni lezzetler gibi kazançlar; yerel kültürlerin zayıflaması, salgınların hızla yayılması ve çevre sorunları gibi riskler.'},
  u2_sinir:{m:'Sınır Sanan',c:'#22aaff',t:'Bir ülkedeki gelişmenin ya da sorunun sınırda durduğunu, küresel sorunların tek başına çözülebileceğini sanıyor.',s:'Küresel sorunlar tüm dünyayı etkiler; çözümü iş birliği ister.',d:'COVID-19 salgını ve iklim krizi örneklerinde olduğu gibi küreselleşen dünyada sorunlar sınır tanımaz. Kitap, ülkelerin dayanışma ve ortak sorumlulukla birlikte hareket etmesini vurgular.'},
  u2_kavram:{m:'Kavram Karıştıran',c:'#aa44ff',t:'Göç, mülteci, insani yardım, ara bulucu, barış gibi kavramları birbirine karıştırıyor.',s:'Her kavramın kitaptaki tanımına dön.',d:'Örneğin göç daha iyi yaşam ya da güvenlik için yer değiştirmektir; mülteci ise savaş, çatışma veya baskı yüzünden ülkesini terk etmek zorunda kalan kişidir. Ara bulucu taraf tutmaz, uzlaşmayı sağlar.'},
  u2_kanit:{m:'Kanıt Atlayan',c:'#ff4f7a',t:'Kaynakta yazmayan bir şeyi kaynağın söylediğini sanıyor ya da görüşü kanıt yerine koyuyor.',s:'Önce kaynağın gerçekten ne dediğine bak.',d:'Kaynak sorularında çocuk metindeki bilgiyle kendi tahminini ayırmalı; çıkarım, kaynaktaki ifadelere dayanmalıdır. Sloganlar ve kişisel yorumlar kanıt değildir.'},
  u2_yon:{m:'Yön Şaşırtan',c:'#22aa55',t:'Kitapta adı geçen ülkelerin haritadaki yerini karıştırıyor.',s:'Türkiye’yi bul, sonra komşularına ve kıtalara bak.',d:'Haritada önce Türkiye’yi merkez alıp yön bulmak (doğusu, batısı, Afrika, Asya) yeri hatırlamayı kolaylaştırır.'},
  u2_neden:{m:'Neden-Sonuç Karıştıran',c:'#e0a800',t:'Bir olayın nedenini sonucuyla karıştırıyor.',s:'“Hangisi önce oldu, hangisi onun yüzünden oldu?” diye sor.',d:'Örneğin fosil yakıt kullanımı ve ormanların kesilmesi iklim krizinin nedenleridir; kuraklık, sel ve sıcaklık artışı ise sonuçlarıdır.'},
  u2_kultur:{m:'Kökünü Unutan',c:'#ff6ec7',t:'Küreselleşmeye uymak için yerel kültürü, dili ve değerleri bırakmak gerektiğini sanıyor.',s:'Başka kültürleri tanımak kadar millî kültüre sahip çıkmak da önemlidir.',d:'Kitap özgürlüğün sorumlulukla anlam kazandığını, bireylerin dilini, kültürünü ve millî-manevi değerlerini koruması gerektiğini söyler; Kültür Yolu Festivalleri buna örnektir.'},
  u2_tarih:{m:'Tarih Karıştıran',c:'#00b8a9',t:'Kitapta geçen yakın tarihli olayların sırasını karıştırıyor.',s:'Yılları küçükten büyüğe diz.',d:'Bu öğrenme alanındaki olaylar 2015’ten 2025’e uzanır; 2053 ise ileriye dönük bir hedeftir, olmuş bir olay değildir.'}
});

/* ---------- 2-1 ---------- */
FEN.lesson({id:'2-1',t:'Küreselleşme nedir?',p:'56–60',kw:'küreselleşme tanım COVID-19 salgın Kağan ekonomi ticaret Sanayi İnkılabı ihracat',script:[
 ['Görev','Merhaba kaşif! Bu öğrenme alanının adı Evimiz Dünya. Bugün dünyanın nasıl birbirine bağlandığını keşfedeceğiz. Bu sürecin adı küreselleşme.',[
   ['title','Küreselleşme nedir?','s. 56–60'],['txt','Dünya küçülüyor mu, yoksa birbirine mi bağlanıyor?',300,' st-cyan']]],
 ['Tanım','Sözlüğe bakalım. Küreselleşme, dünyanın ekonomik, kültürel ve siyasi olarak birbirine daha bağlı hâle gelmesidir. Bu süreç yalnızca bireyleri değil toplumları da etkiler.',[
   ['source',{t:'belge',title:'Sözlükte küreselleşme',by:'Ders kitabı sözlüğü',text:'Küreselleşme: Dünyanın ekonomik, kültürel ve siyasi olarak birbirine daha bağlı hâle gelmesi.'},['ekonomik','kültürel','siyasi']]]],
 ['Örnekler','Eskiden aylar süren yolculuklar şimdi birkaç saat sürüyor. Genel ağ sayesinde dünyanın öbür ucuna saniyede merhaba diyebiliyoruz. Yeni lezzetler tadıyoruz. Bir ülkedeki aşı çalışması tüm dünyaya yarayabilir, ama bir hastalık da aynı hızla her yere yayılabilir.',[
   ['cards',[['✈️','Ulaşım','Aylar süren yol saatlere'],['💬','Genel ağ','Saniyeler içinde merhaba'],['🍜','Kültür','Yeni lezzet, yeni kültür'],['💉','Sağlık','Aşı da hastalık da yayılır']]]]],
 ['Kağan','İki bin yirmi yılında yedinci sınıf öğrencisi Kağan, Çin’de ortaya çıkıp kısa sürede tüm dünyaya yayılan COVID-19 salgınına tanık oldu. Kısıtlamalar başladı, Kağan derslere uzaktan katıldı. Ülkeler arasında giriş çıkışların yasaklanması ticareti olumsuz etkiledi.',[
   ['map','dunya',[['country','CHN','Çin'],['country','TUR','Türkiye']]],
   ['chain',[['🦠','Çin’de salgın'],['🌍','Dünyaya yayıldı'],['🏠','Kısıtlamalar'],['💻','Uzaktan eğitim'],['📉','Ticaret etkilendi']],330]]],
 ['Ekonomi','Sanayi İnkılabı’ndan önce ulaşım ve iletişim sınırlıydı; ekonomik faaliyetlerin çoğu ülke içinde yapılırdı. Hızlı trenler, dev kargo gemileri, uçaklar, genel ağ ve uydular sayesinde ticaret dünya çapına yayıldı. Büyük uluslararası şirketlerin sayısı arttı.',[
   ['compare',['İnkılap öncesi','Günümüz'],[['Sınırlı ulaşım, iletişim','Hızlı tren, kargo gemisi'],['Ticaret ülke içinde','Ticaret dünya çapında'],['Uzak ürüne ulaşmak zor','Başka ülke ürünü kolay'],['Az uluslararası şirket','Çok uluslararası şirket']]]]],
 ['Tuzak','Dikkat! Küreselleşme yalnızca iyilik getirmez. Kitap sorunları da sayar: yerel kültürlerin zayıflaması, salgınların hızla yayılması, çevre sorunlarının artması, zenginliklerin adil paylaşılmaması ve küçük yerel işletmelerin zor durumda kalması.',[
   ['trap','Küreselleşme yalnızca iyi şeyler getirir.'],
   ['lines',['Yerel kültürler zayıflayabilir','Salgın hastalıklar hızla yayılır','Çevre sorunları artar','Zenginlik adil paylaşılmayabilir','Küçük yerel işletmeler zorlanır'],200]]],
 ['Özet','Özetleyelim. Küreselleşme dünyanın her alanda birbirine bağlanmasıdır. Ekonomi, ulaşım, iletişim, kültür, sağlık ve çevre en çok etkilenen alanlardır. Olumlu ve olumsuz yönleri birlikte düşünmeliyiz.',[
   ['rules',['Küreselleşme: dünyanın birbirine daha bağlanması','Ekonomik, kültürel ve siyasi bağlar güçlenir','Etkili alanlar: ekonomi, ulaşım, iletişim…','…kültür, sağlık ve çevre','Hem olumlu hem olumsuz etkileri vardır'],150]]]],
 q:[
  {k:'mc',p:'Kitaba göre küreselleşme nedir?',a:'Dünyanın ekonomik, kültürel ve siyasi olarak birbirine daha bağlanması',w:[['Bir ülkenin başka ülkelerle tüm ilişkisini kesmesi','u2_kavram'],['Yalnızca uçakla yapılan yolculukların artması','u2_kavram'],['Bir şehrin nüfusunun hızla artması','other']],e:'Küreselleşme; ekonomi, kültür ve siyasette dünyanın birbirine daha bağlı hâle gelmesi sürecidir.'},
  {k:'mc',p:'Kitaba göre küreselleşmenin etkisinin en belirgin görüldüğü alanlar hangileridir?',a:'Ekonomi, ulaşım, iletişim, kültür, sağlık ve çevre',w:[['Yalnızca spor ve eğlence','u2_kavram'],['Yalnızca tarım ve hayvancılık','u2_kavram']],e:'Kitap bu altı alanı küreselleşmenin en belirgin görüldüğü yerler olarak sayar.'},
  {k:'tf',p:'Bir ülkede ulaşım ve iletişim alanında meydana gelen gelişmeler diğer ülkelerdeki insanları etkilemez.',a:false,mis:'u2_sinir',e:'Yanlış. Küreselleşen dünyada bir ülkedeki gelişme kısa sürede başka ülkeleri de etkiler.'},
  {k:'tf',p:'Küreselleşme yalnızca bireyleri değil toplumları da etkiler.',a:true,mis:'u2_kavram',e:'Doğru. Kitap küreselleşmenin hem bireyleri hem toplumları etkilediğini söyler.'},
  {k:'src',src:{t:'belge',title:'Kağan’ın salgın günleri',by:'Ders kitabındaki örnek olay (özet)',date:'2020',text:'Kağan, Sağlık Bakanlığının uyarılarına göre hareket etti ve doğru bilgi için resmî kaynakları izledi. Okuduğu kaynaklarda, salgını durdurmak için ülkeler arasında giriş çıkışların yasaklanmasının ticareti olumsuz etkilediğini gördü.'},p:'Bu kaynağa göre ülkeler arası giriş çıkış yasakları en çok neyi olumsuz etkiledi?',a:'Ticareti',w:[['Uzaktan eğitimi','u2_kanit'],['Hava durumunu','other']],e:'Kaynakta açıkça giriş çıkış yasaklarının ticareti olumsuz etkilediği yazıyor.'},
  {k:'src',src:{t:'belge',title:'Kağan’ın salgın günleri',by:'Ders kitabındaki örnek olay (özet)',date:'2020',text:'Kağan, merak ettiklerini öğretmenlerine sordu ve not aldı. Evde kaldığı sürede doğru bilgilere ulaşmak için resmî kaynakları takip etti; Halk Sağlığı Genel Müdürlüğünün uyarılarına göre hareket etti.'},p:'Kağan’ın davranışından hangi sonuca ulaşılabilir?',a:'Doğru bilgi için güvenilir ve resmî kaynaklar izlenmelidir.',w:[['Her duyduğu habere hemen inanmıştır.','u2_kanit'],['Salgın hakkında hiç bilgi almamıştır.','u2_kanit']],e:'Kağan öğretmenlerine sormuş ve resmî kaynakları izlemiştir; bu, güvenilir kaynak seçmenin önemini gösterir.'},
  {k:'mc',p:'Kağan’ın öyküsüne göre hastalık neden kısa sürede birçok ülkeye yayıldı?',a:'Ülkeler arasında ulaşımın hızlı olması nedeniyle',w:[['Ülkeler arasında hiç ulaşım olmaması nedeniyle','u2_neden'],['Uzaktan eğitim yapılması nedeniyle','u2_neden']],e:'Hızlı ulaşım insanları ve onlarla birlikte hastalıkları da kısa sürede başka ülkelere taşır.'},
  {k:'mc',p:'Ülkeler salgınla ilgili araştırma sonuçlarını paylaşıp ortak çözüm geliştirebildi. Bunu en çok hangi alandaki gelişmeler sağladı?',a:'İletişim teknolojisindeki gelişmeler',w:[['Tarım alanındaki gelişmeler','u2_neden'],['Kıyafet modasındaki değişimler','other']],e:'İletişim teknolojileri bilginin dünyada hızla paylaşılmasını sağlar.'},
  {k:'sort',p:'Küreselleşmenin etkilerini olumlu ve olumsuz diye ayır.',bins:['Olumlu','Olumsuz'],items:[['Yeni lezzetler tatmak',0],['Saatler süren yolculuk',0],['Bilgiye kolay ulaşmak',0],['Yerel kültür zayıflar',1],['Salgın hızla yayılır',1],['Çevre sorunları artar',1],['Küçük işletme zorlanır',1]],mis:'u2_tekyon',e:'Küreselleşme kolaylıklar getirir ama yerel kültür, sağlık, çevre ve küçük işletmeler için riskler de taşır.'},
  {k:'mc',p:'Sanayi İnkılabı öncesinde ekonomik faaliyetler nasıldı?',a:'Büyük kısmı ülke sınırları içinde yapılırdı.',w:[['Hepsi genel ağ üzerinden yapılırdı.','u2_tarih'],['Büyük uluslararası şirketler her yerdeydi.','u2_tarih']],e:'Ulaşım ve iletişim sınırlı olduğu için ticaret daha çok ülke içinde kalıyordu.'},
  {k:'mc',p:'Ticaretin dünya çapında bir boyut kazanmasını ne sağladı?',a:'Modern ulaşım araçları ve gelişmiş iletişim teknolojileri',w:[['Ülkelerin sınırlarını kapatması','u2_neden'],['Yolculukların daha uzun sürmesi','u2_neden']],e:'Hızlı tren, kargo gemisi, uçak, genel ağ, akıllı telefon ve uydular ticareti dünyaya yaydı.'},
  {k:'mc',p:'Kitaba göre küreselleşmenin ekonomide getirdiği sorunlardan biri hangisidir?',a:'Zenginliklerin adil paylaşılmaması',w:[['Farklı ülkelerin ürünlerine ulaşmanın kolaylaşması','u2_tekyon'],['Ticaretin dünya çapına yayılması','u2_tekyon']],e:'Hızlı değişim, zenginliklerin adil paylaşılmaması ve küçük yerel işletmelerin zorlanması gibi sorunlar getirdi.'},
  {k:'src',src:{t:'belge',title:'Türkiye 2015–2025 ihracat grafiği',by:'Türkiye İhracatçılar Meclisi',date:'2025',text:'Kitaptaki grafik, Türkiye’nin 2015 ile 2025 yılları arasındaki ihracatını gösteriyor. Grafikte 2020 yılında ihracatta bir düşüş görülüyor.'},p:'2020 yılındaki düşüşte dünyada yaşanan hangi gelişme etkili olmuş olabilir?',a:'COVID-19 salgını ve ülkeler arası giriş çıkış yasakları',w:[['Orta Koridorun açılması','u2_neden'],['E-ticaretin yaygınlaşması','u2_neden']],e:'Kitap, salgın döneminde giriş çıkış yasaklarının ticareti olumsuz etkilediğini anlatır; bu, 2020 düşüşünü açıklayabilir.'},
  {k:'sc',role:'2020 yılındasın. Salgın yeni başladı ve okullar uzaktan eğitime geçti. Ailen de sen de endişelisin.',steps:[
    {p:'Bir mesajlaşma grubunda “Bu salgın birkaç güne biter, önlem gereksiz.” diye bir mesaj dolaşıyor. Ne yaparsın?',o:[['Sağlık Bakanlığının resmî açıklamalarına bakarım',2,'Doğru! Kağan da doğru bilgi için resmî kaynakları izledi.'],['Öğretmenime sorarım',1,'İyi bir adım; resmî kaynaklara da bakarsan bilgin daha sağlam olur.'],['Mesajı hemen herkese gönderirim',0,'Kaynağı belli olmayan bilgi kanıt değildir; yanlış bilgi de salgın gibi hızla yayılır.','u2_kanit']]},
    {p:'Evde kalmaktan sıkıldın. Dersler ekrandan devam ediyor. Ne yaparsın?',o:[['Uzaktan derslere düzenli katılırım',2,'Harika! Kağan da eğitimini uzaktan derslerle sürdürdü.'],['Kısıtlamayı tatil sayıp dersleri bırakırım',0,'Kağan da başta tatil sandı; ama eğitim devam ediyordu.','u2_kavram']]},
    {p:'Dedeni çok özledin ama uyarılar ziyaret etmemeyi öneriyor. Ne yaparsın?',o:[['Uyarılara uyar, onunla görüntülü görüşürüm',2,'İletişim teknolojisi uzaktaki yakınlarla bağı korur, sağlığı da korursun.'],['Kimseye söylemeden ziyarete giderim',0,'Hastalık hızla yayılabilir; uyarılar herkesi korumak içindir.','u2_sinir'],['Hiç haberleşmem',1,'Sağlığı korursun ama iletişim imkânlarından yararlanabilirdin.']]}],
   e:'Küresel bir salgında doğru bilgi resmî kaynaklardan alınır; teknoloji eğitimi ve iletişimi sürdürmeye yardım eder; kurallara uymak herkesi korur.'},
  {k:'map',map:'dunya',p:'Kağan’ın öyküsünde COVID-19 salgınının ortaya çıktığı ülkeyi haritada bul.',a:'CHN',w:['JPN','IND','RUS'],mis:'u2_yon',e:'Kitaba göre salgın Çin’de ortaya çıktı ve kısa sürede tüm dünyaya yayıldı.'},
  {k:'order',p:'Kağan’ın öyküsündeki olayları oluş sırasına diz.',items:['Salgın Çin’de çıktı','Salgın dünyaya yayıldı','Türkiye’de görüldü','Kısıtlama, uzaktan ders'],mis:'u2_neden',e:'Salgın önce Çin’de çıktı, dünyaya yayıldı, Türkiye’de görüldü; ardından kısıtlamalar ve uzaktan eğitim başladı.'},
  {k:'mc',p:'“Bir ülkedeki aşı çalışması tüm dünyayı kurtarabilir ama bir hastalık da aynı hızla her yere yayılabilir.” Bu cümle neyi gösterir?',a:'Küreselleşmenin hem olumlu hem olumsuz yönü olduğunu',w:[['Küreselleşmenin yalnızca iyi sonuçlar doğurduğunu','u2_tekyon'],['Sağlığın küreselleşmeden hiç etkilenmediğini','u2_sinir']],e:'Aynı bağlantılar hem iyiliği hem sorunu hızla yayar; küreselleşmenin iki yüzü vardır.'},
  {k:'tf',p:'Küreselleşme ile birlikte dünyanın birçok yerinde çalışan büyük uluslararası şirketlerin sayısı azaldı.',a:false,mis:'u2_neden',e:'Yanlış. Kitaba göre ticaretin dünyaya yayılmasıyla bu şirketlerin sayısı arttı.'}]});

/* ---------- 2-2 ---------- */
FEN.lesson({id:'2-2',t:'Ulaşım, iletişim ve kültür',p:'61–63',kw:'ulaşım Orta Koridor iletişim genel ağ e-ticaret kültür popüler kültür ana dil kahve',script:[
 ['Görev','Bugün üç alana bakacağız: ulaşım, iletişim ve kültür. Küreselleşme bu alanlarda hayatımızı nasıl değiştirdi? Hadi başlayalım.',[
   ['title','Ulaşım, iletişim ve kültür','s. 61–63'],['cards',[['🚄','Ulaşım','Daha hızlı, daha çok yük'],['📱','İletişim','Bilgi her yerde'],['🎶','Kültür','Etkileşim ve koruma']]]]],
 ['Ulaşım','Geçmişte insanlar az yük taşıyan, yavaş araçlarla uzun yolculuklar yapardı. Sanayi İnkılabı sonrasında hem daha büyük hem daha hızlı taşıtlar yapıldı. Yolculuklar kolaylaşınca iş ve turizm amaçlı seyahatler arttı, toplumlar birbiriyle daha çok etkileşim kurdu.',[
   ['compare',['Geçmiş','İnkılap sonrası'],[['Az yük taşıyan araçlar','Büyük kapasiteli taşıtlar'],['Yavaş ve uzun yolculuk','Hızlı ve kolay yolculuk'],['Az seyahat','Çok iş ve turizm seyahati'],['Az etkileşim','Daha fazla etkileşim']]]]],
 ['Orta Koridor','Orta Koridor, Trans-Hazar Uluslararası Taşımacılık Koridoru olarak da bilinir. Çin’in doğusundan başlar; Kazakistan, Hazar Denizi, Azerbaycan ve Gürcistan üzerinden Türkiye’ye, oradan da Avrupa’ya uzanır. Türkiye yeni yatırımlarla bu yoldaki yerini güçlendiriyor.',[
   ['map','dunya',[['country','CHN','Çin'],['country','KAZ','Kazakistan'],['country','AZE','Azerbaycan'],['country','GEO','Gürcistan'],['country','TUR','Türkiye']]],
   ['txt','Demir yolu ticaret potansiyeli: 75 milyar dolar',380,' st-gold']]],
 ['İletişim','Genel ağ ve mobil cihazlar bilgiye ulaşmayı kolaylaştırdı. Görüntülü görüşmeyle uzaktaki yakınlarımızla canlı konuşuyoruz. Trafikte akıllı telefon uygulamaları alternatif yolu gösteriyor. E-ticaretle evden çıkmadan başka ülkelerden alışveriş yapılabiliyor.',[
   ['cards',[['🎥','Görüntülü görüşme','Uzaktakiyle canlı konuşma'],['🚗','Trafik uygulaması','Alternatif yolu anında bul'],['🛒','E-ticaret','Evden dünyaya alışveriş'],['🩺','Çevrim içi ortam','Çevrim içi eğitim, sağlık']]]]],
 ['Kültür','İnsanlar somut ve somut olmayan pek çok kültürel miras ögesi oluşturmuştur. Küreselleşmeyle bu ögeler başka ülkelere taşındı. Bu, kültürel çeşitliliği artırabilir; ama yerel kültürleri yok olma tehlikesiyle de karşı karşıya bırakabilir. Ana dile çok fazla yabancı sözcük girmesi de millî dili bozabilir.',[
   ['compare',['Kazanç','Tehlike'],[['Kültürel çeşitlilik artar','Yerel kültür yok olabilir'],['Başka kültürleri tanırız','Popüler kültür baskın olur'],['Kültür ögeleri tanınır','Ana dil bozulabilir']]]]],
 ['Tuzak','Tuzağa düşme! Başka kültürleri tanımak, kendi kültürünü bırakmak demek değildir. Kitap şöyle der: Küreselleşen dünyada başka kültürleri tanımak ne kadar önemliyse millî kültüre sahip çıkmak da o kadar önemlidir.',[
   ['trap','Yeni kültür için eskisini bırakmak gerekir.'],['tip','Tanı, ama kendi kültürüne de sahip çık.']]],
 ['Özet','Özetleyelim. Hızlı ulaşım etkileşimi artırdı, Orta Koridor Türkiye’yi ticaret yolunun ortasına koydu. İletişim teknolojileri günlük hayatı kolaylaştırdı. Kültürel etkileşim çeşitlilik getirdi ama millî kültürü korumak da gerekiyor.',[
   ['rules',['Hızlı ulaşım → daha çok iş ve turizm seyahati','Orta Koridor: Çin’den Türkiye üzerinden Avrupa’ya','Genel ağ ve mobil cihaz → bilgiye kolay erişim','E-ticaret: evden başka ülkeyle alışveriş','Başka kültürü tanı, millî kültüre sahip çık'],150]]]],
 q:[
  {k:'mc',p:'Sanayi İnkılabı sonrasındaki teknolojik gelişmeler ulaşımı nasıl değiştirdi?',a:'Daha büyük kapasiteli ve çok daha hızlı taşıtlar yapıldı.',w:[['Taşıtlar daha yavaş ve küçük hâle geldi.','u2_tarih'],['İnsanlar uzak yolculuk yapmayı bıraktı.','u2_neden']],e:'Hem daha çok yük taşıyan hem daha hızlı taşıtlar uzak yolculukları kolaylaştırdı.'},
  {k:'mc',p:'Yolculukların kolay ve hızlı olması hangi sonucu doğurdu?',a:'İş ve turizm amaçlı seyahatler arttı.',w:[['İnsanlar arasındaki etkileşim azaldı.','u2_neden'],['Ticaret yalnızca ülke içinde kaldı.','u2_neden']],e:'Kolay ulaşım seyahatleri artırdı ve toplumlar arasında daha çok etkileşime zemin hazırladı.'},
  {k:'src',src:{t:'gazete',title:'Orta Koridor ve Türkiye',by:'Genel ağdan alınan haber (kitapta)',text:'Orta Koridor, Çin’in doğusundan başlayıp Kazakistan, Hazar Denizi, Azerbaycan ve Gürcistan üzerinden Türkiye’ye, buradan da Avrupa’ya uzanıyor. Türkiye, yeni yatırımlar ve terminal kapasitesindeki artışla güzergâhtaki konumunu güçlendiriyor.'},p:'Bu habere göre Orta Koridor hangi güzergâhı izler?',a:'Çin’den Orta Asya ve Kafkasya üzerinden Türkiye’ye ve Avrupa’ya',w:[['Avrupa’dan Afrika üzerinden Amerika’ya','u2_yon'],['Türkiye’den başlayıp yalnızca Çin’e','u2_kanit']],e:'Haberde güzergâh Çin, Kazakistan, Hazar Denizi, Azerbaycan, Gürcistan, Türkiye ve Avrupa olarak verilir.'},
  {k:'src',src:{t:'gazete',title:'Orta Koridor Türkiye’yi merkeze taşıyor',by:'Genel ağdan alınan haber (kitapta)',text:'Orta Koridorun demir yolu üzerinde ticaret hacmi potansiyeli 75 milyar dolar seviyesinde. Güzergâh küresel ticarette önem kazanırken Türkiye yeni yatırımlarla konumunu güçlendiriyor.'},p:'Bu kaynaktan hangi sonuca ulaşılabilir?',a:'Konumu, Türkiye’yi Asya-Avrupa ticaretinde önemli kılar.',w:[['Orta Koridorun Türkiye’ye hiçbir katkısı yoktur.','u2_kanit'],['Orta Koridor yalnızca turistler için yapılmıştır.','u2_kanit']],e:'Haber, koridorun ticaretteki önemini ve Türkiye’nin güzergâhtaki konumunu güçlendirdiğini anlatır.'},
  {k:'map',map:'dunya',p:'Orta Koridorda yükler Türkiye’ye ulaşmadan hemen önce hangi ülkeden geçer? Haritada bul.',a:'GEO',w:['ARM','IRN','BGR'],mis:'u2_yon',e:'Güzergâh Azerbaycan’dan sonra Gürcistan üzerinden Türkiye’ye ulaşır.'},
  {k:'map',map:'dunya',p:'Orta Koridor Çin’den sonra Hazar Denizi’ne ulaşmadan önce hangi ülkeden geçer? Haritada bul.',a:'KAZ',w:['RUS','UZB','TKM'],mis:'u2_yon',e:'Kitaptaki habere göre koridor Çin’den Kazakistan’a, oradan Hazar Denizi’ne uzanır.'},
  {k:'sort',p:'Örnekleri ulaşım ve iletişim diye ayır.',bins:['Ulaşım','İletişim'],items:[['Hızlı tren',0],['Dev kargo gemisi',0],['Uçak',0],['Genel ağ',1],['Akıllı telefon',1],['Uydu',1],['Görüntülü görüşme',1]],mis:'u2_kavram',e:'Ulaşım insanları ve yükleri taşır; iletişim bilgiyi ses, yazı ve görüntü olarak iletir.'},
  {k:'mc',p:'Kitaba göre e-ticaret insanlara hangi kolaylığı sağlar?',a:'Evden çıkmadan başka ülkelerle alışveriş yapabilmeyi',w:[['Yalnızca mahalle pazarından alışveriş yapmayı','u2_kavram'],['Para kullanmadan takas yapmayı','u2_kavram']],e:'E-ticaret sayesinde evden çıkmadan başka ülkelerden alışveriş yapılabilir.'},
  {k:'mc',p:'Büyük şehirlerde trafiğin yoğun olduğu saatlerde akıllı telefon uygulamalarıyla alternatif yol öğrenmek neye örnektir?',a:'İletişimdeki gelişmelerin günlük hayatı kolaylaştırmasına',w:[['Ulaşım araçlarının yavaşlamasına','u2_neden'],['Yerel kültürün zayıflamasına','u2_kavram']],e:'Kitap bunu iletişim sektöründeki gelişmelerin günlük yaşama getirdiği kolaylıklara örnek verir.'},
  {k:'mc',p:'Görüntülü ve sesli iletişim cihazları ekonomiyi nasıl etkiledi?',a:'Ekonomik ilişkileri hızlandırdı.',w:[['Ekonomik ilişkileri tamamen durdurdu.','u2_neden'],['Ekonomiyi hiç etkilemedi.','u2_sinir']],e:'Kitaba göre bu cihazlar sayesinde ekonomik ilişkiler hızlandı.'},
  {k:'tf',p:'Kültürel ögelerin başka ülkelere taşınması bazı toplumların kültürel çeşitliliğini artırabilir, ama yerel kültürleri de yok olma tehlikesine sokabilir.',a:true,mis:'u2_tekyon',e:'Doğru. Kitap kültürel etkileşimin bu iki yönünü birlikte anlatır.'},
  {k:'mc',p:'Kitaba göre bir ülkenin kültüründen hangi ögeler başka kültürlere yerleşebilir?',a:'Kıyafet, yemek, müzik ve eğlence anlayışı',w:[['Dağlar, nehirler ve göller','u2_kavram'],['İklim ve yer şekilleri','u2_kavram']],e:'Kültür ögeleri insan yapımıdır: kıyafet, yemek, müzik, eğlence anlayışı gibi.'},
  {k:'mc',p:'Kitaba göre kültürel değişimin en bilinen örneği hangisidir?',a:'Popüler kültür ve onun yol açtığı değişim',w:[['Mevsimlerin değişmesi','u2_kavram'],['Hızlı trenlerin yapılması','u2_kavram']],e:'Kitap, popüler kültürü ve sonucunda oluşan değişimi en bilinen örnek olarak verir.'},
  {k:'src',src:{t:'alinti',title:'Dilimiz ve küreselleşme',by:'Ders kitabından (özet)',text:'Ana dile başka dillerden çok fazla sözcük girmesi, millî dillerin bozulmasına ve zamanla unutulmasına sebep olabilir. Bu yüzden başka kültürleri tanımak ne kadar önemliyse millî kültüre sahip çıkmak da o kadar önemlidir.'},p:'Bu kaynağa göre hangi davranış doğrudur?',a:'Gereksiz yabancı sözcükler yerine Türkçe karşılıklarını kullanmak',w:[['Türkçe sözcükleri bırakıp yabancı sözcük kullanmak','u2_kultur'],['Başka kültürleri tanımayı tamamen reddetmek','u2_tekyon']],e:'Kaynak hem başka kültürleri tanımayı hem de ana dili ve millî kültürü korumayı önemli sayar.'},
  {k:'tf',p:'Küreselleşen dünyada millî kültüre sahip çıkmak önemini yitirmiştir.',a:false,mis:'u2_kultur',e:'Yanlış. Kitaba göre küreselleşen dünyada millî kültüre sahip çıkmak daha da önemli hâle gelmiştir.'},
  {k:'order',p:'Kitaba göre bir kültür ögesinin başka bir kültüre yerleşme yolunu sırala.',items:['Kültür ögesi oluşturulur','Ülkelerce tanınır','Başka ülkelere taşınır','Başka kültüre yerleşir'],mis:'u2_neden',e:'İnsanlar kültürel miras ögeleri oluşturur; küreselleşmeyle bunlar tanınır, taşınır ve başka kültürlere yerleşebilir.'},
  {k:'src',src:{t:'belge',title:'Kahvenin Yolculuğu',by:'Ders kitabındaki etkinlik sorusu',text:'Yurt dışından ithal edilen kahve çekirdekleri Türk üreticilerin elinde nasıl dünya markasına dönüşmüştür?'},p:'Bu soruya göre kahve çekirdekleri nereden gelir?',a:'Yurt dışından ithal edilir.',w:[['Türkiye’de yetiştirilir.','u2_kanit'],['Kaynakta hiç söz edilmez.','u2_kanit']],e:'Soru metni çekirdeklerin yurt dışından ithal edildiğini, Türk üreticilerin ise onu dünya markasına dönüştürdüğünü söyler.'},
  {k:'sc',role:'Sınıfın, yurt dışındaki bir okulla görüntülü görüşme projesine katılıyor. Sen sınıfın sunucususun.',steps:[
    {p:'Yabancı arkadaşlar Türkiye’yi tanımak istiyor. Ne hazırlarsın?',o:[['Kendi kültürümüzü anlatır, onların kültürünü de sorarım',2,'Güzel! Karşılıklı tanışmak kültürel çeşitliliği artırır, kendi kültürünü de tanıtırsın.'],['Yalnızca onların sevdiği popüler şarkıları anlatırım',0,'Böyle kendi kültürünü unutursun; popüler kültür yerel kültürü zayıflatabilir.','u2_kultur'],['Sadece onları dinlerim',1,'Dinlemek iyi ama kendi kültürünü de tanıtabilirdin.']]},
    {p:'Görüşmeden sonra okul gazetesine yazı yazacaksın. Hangi dili seçersin?',o:[['Türkçe sözcükleri özenle kullanırım',2,'Harika! Ana dile gereksiz yabancı sözcük sokmamak dili korur.'],['Havalı dursun diye yabancı sözcük doldururum',0,'Çok fazla yabancı sözcük millî dili bozabilir.','u2_kultur']]}],
   e:'Küreselleşen dünyada başka kültürleri tanımak güzeldir; aynı anda kendi dilimize, kültürümüze ve değerlerimize sahip çıkmak gerekir.'}]});

/* ---------- 2-3 ---------- */
FEN.lesson({id:'2-3',t:'Sağlık, çevre ve değerlerimiz',p:'63–67',kw:'sağlık TİKA Senegal çevre sorunları Yeşil Vatan yerelden evrensele israf millî manevi değerler Kültür Yolu',script:[
 ['Görev','Bu derste küreselleşmenin sağlığa, çevreye ve değerlerimize etkisini inceleyeceğiz. Sonunda çevre için kendi okulunda neler yapabileceğine karar vereceksin.',[
   ['title','Sağlık, çevre ve değerlerimiz','s. 63–67'],['txt','Dünya ortak evimiz: onu nasıl koruruz?',300,' st-cyan']]],
 ['Sağlık','Bilim ve teknoloji geliştikçe hastalıkların teşhis ve tedavisi kolaylaştı, başka ülkelerde tedavi olma imkânı arttı. Ama küreselleşme hastalıkların yayılmasını da hızlandırdı. COVID-19 salgını bunun en somut örneğidir.',[
   ['compare',['Kazanç','Risk'],[['Teşhis ve tedavi kolay','Hastalık hızla yayılır'],['Başka ülkede tedavi','Sorun tüm dünyayı etkiler'],['Ülkeler iş birliği yapar','Örnek: COVID-19 salgını']]]]],
 ['TİKA','Türk İş Birliği ve Koordinasyon Ajansı Başkanlığı, yani TİKA, Senegal’in Touba kentindeki bir sağlık merkezinin acil servisini modern tıbbi ekipmanlarla donattı. Bu merkez yılda yaklaşık yirmi beş bin kişiye hizmet veriyor.',[
   ['source',{t:'gazete',title:'TİKA’dan Senegal’e sağlık desteği',by:'Genel ağdan alınan haber (kitapta)',text:'TİKA, Senegal’in Touba kentindeki Ndamatou Halk Sağlığı Merkezinin acil servis birimini modern tıbbi ekipmanlarla donattı. Yılda yaklaşık 25 bin kişiye hizmet veren merkeze hasta yatakları ve monitörler verildi.'},['modern tıbbi ekipmanlarla','25 bin kişiye']]]],
 ['Çevre','Küreselleşmeyle artan üretim, tüketim ve ulaşım doğal kaynakların daha yoğun kullanılmasına yol açtı. Karbon salınımı arttı, doğal yaşam alanları tahrip oldu. Bu sorunlar yerel olmaktan çıktı; iklim krizi, küresel ısınma, ormansızlaşma ve su kirliliği gibi küresel sorunlara dönüştü.',[
   ['chain',[['🏭','Üretim, tüketim'],['⛏️','Kaynak tükenir'],['💨','Karbon, kirlilik'],['🌡️','Küresel sorunlar']],160],
   ['lines',['İklim krizi, küresel ısınma','Biyolojik çeşitlilik kaybı, ormansızlaşma','Toprak erozyonu, atıklar, su kirliliği'],290]]],
 ['Yeşil Vatan','İki bin yirmi beş, iki bin yirmi altı eğitim öğretim yılında ülkemizin her bölgesinde Yeşil Vatan, Benim Okulum Geleceğe Çare etkinlikleri başladı. Okulların ilk günü film gösterimi ve fidan hediyeleriyle başlayan bu yolculuk, yıl boyunca atölyeler ve saha çalışmalarıyla sürüyor.',[
   ['source',{t:'afis',title:'Yeşil Vatan - Benim Okulum Geleceğe Çare',by:'Genel ağdan alınan haber (kitapta)',date:'2025-2026',text:'"Yeşil Vatan’ı korumak, vatanı korumaktır!" Okulların açıldığı ilk gün film gösterimi ve fidan hediyeleriyle başlayan yolculuk yıl boyunca etkinlik, atölye ve saha çalışmalarıyla sürecek.'},['vatanı korumaktır','fidan hediyeleriyle']]]],
 ['Yerelden evrensele','Küresel çevre sorunlarının çözümü uluslararası dayanışma ister, ama harekete geçiş noktası bireyin kendi yaşam alanıdır. Buna yerelden evrensele ilkesi denir. En temel yollar: bilinçli üretim, ihtiyaç kadar alan bilinçli tüketim ve israfı önlemek.',[
   ['cycle',[['🏠','Ben ve evim'],['🏫','Okulum'],['🏙️','Ülkem'],['🌍','Dünya']],'Yerelden dünya'],
   ['txt','Bilinçli üretim · bilinçli tüketim · israfa son',390,' st-ok']]],
 ['Değerler','Küreselleşmeyle konuşma dilinde bozulmalar, hazır gıda tüketiminin artması, aşırı ve gereksiz alışveriş görülebiliyor. Özgürlük önemli bir değerdir ama sorumlulukla anlam kazanır. Kültür Yolu Festivalleri, el sanatlarımızı ve millî musikimizi modern etkinliklerle gençlere ulaştırıyor.',[
   ['trap','Özgürlük, her istediğini düşünmeden yapmaktır.'],
   ['cards',[['📺','Eleştirel düşün','Medya içeriğini seçerken'],['🛍️','Bilinçli tüket','Gereksiz alışverişe hayır'],['🎻','Kültür Yolu','Geleneği yeni yolla yaşat']]]]],
 ['Özet','Özetleyelim. Küreselleşme sağlıkta iş birliğini artırdı ama hastalıkları da hızlandırdı. Çevre sorunları küresel hâle geldi; çözüm kendi yaşam alanımızda başlar. Özgürlük sorumlulukla anlam kazanır; değerlerimizi koruyarak küreselleşmeden yararlanırız.',[
   ['rules',['Sağlık: kolay tedavi, ama hızlı yayılan hastalık','Çevre sorunları yerelden küresele dönüştü','Yerelden evrensele: çözüm benimle başlar','Bilinçli üretim, bilinçli tüketim, israfa son','Özgürlük sorumlulukla anlam kazanır'],150]]]],
 q:[
  {k:'mc',p:'Küreselleşmenin sağlık alanındaki olumlu etkilerinden biri hangisidir?',a:'Başka ülkelerde tedavi olabilme imkânının artması',w:[['Hastalıkların daha hızlı yayılması','u2_tekyon'],['Tıbbi araştırmaların durması','u2_neden']],e:'Bilim ve teknoloji sayesinde teşhis ve tedavi kolaylaştı, başka ülkelerde tedavi imkânı arttı.'},
  {k:'tf',p:'Küreselleşme hastalıkların yayılmasını yavaşlatmıştır.',a:false,mis:'u2_neden',e:'Yanlış. Kitaba göre küreselleşme nedeniyle hastalıkların yayılması hızlanmıştır.'},
  {k:'src',src:{t:'gazete',title:'TİKA’dan Senegal’e sağlık desteği',by:'Genel ağdan alınan haber (kitapta)',text:'TİKA, Senegal’in Touba kentindeki Ndamatou Halk Sağlığı Merkezinin, Senegal Sağlık Bakanlığınca yeni yapılan acil servis birimini merkezin talebi doğrultusunda modern tıbbi ekipmanlarla donattı.'},p:'Bu habere göre TİKA Senegal’de ne yaptı?',a:'Bir acil servis birimini tıbbi ekipmanlarla donattı.',w:[['Senegal’e yeni bir okul yaptı.','u2_kanit'],['Senegal’e tahıl gemisi gönderdi.','u2_kanit']],e:'Haber, TİKA’nın acil servisin donanımını sağladığını anlatır.'},
  {k:'src',src:{t:'gazete',title:'TİKA’dan Senegal’e sağlık desteği',by:'Genel ağdan alınan haber (kitapta)',text:'Ndamatou Halk Sağlığı Merkezi yılda yaklaşık 25 bin kişiye hizmet veriyor. Acil servise monitörler, hasta yatakları, şırınga pompaları, sedyeler ve başka tıbbi ekipmanlar verildi.'},p:'Bu kaynaktan hangi sonuca ulaşılabilir?',a:'Yardım, binlerce kişinin acil sağlığa ulaşmasını kolaylaştırır.',w:[['Merkez yalnızca birkaç kişiye hizmet verir.','u2_kanit'],['Yardım yalnızca Türkiye’deki hastalar içindir.','u2_kanit']],e:'Yılda 25 bin kişiye hizmet veren merkezin donanımı, birçok insanın acil sağlığına katkı sağlar.'},
  {k:'mc',p:'TİKA hangi kurumun kısa adıdır?',a:'Türk İş Birliği ve Koordinasyon Ajansı Başkanlığı',w:[['Türkiye İhracatçılar Meclisi','u2_kavram'],['Türk Devletleri Teşkilatı','u2_kavram']],e:'Kitapta TİKA, Türk İş Birliği ve Koordinasyon Ajansı Başkanlığı olarak geçer.'},
  {k:'mc',p:'Kitaba göre doğal kaynakların daha yoğun kullanılmasına ne neden olmuştur?',a:'Küreselleşmeyle artan üretim, tüketim ve ulaşım faaliyetleri',w:[['Fidan dikme etkinliklerinin artması','u2_neden'],['İsrafın önlenmesi','u2_neden']],e:'Artan üretim, tüketim ve ulaşım kaynakların yoğun kullanılmasına ve çevre sorunlarına yol açtı.'},
  {k:'sort',p:'Çevre sorunlarıyla ilgili örnekleri neden ve sonuç diye ayır.',bins:['Neden','Sonuç'],items:[['Artan üretim',0],['Artan tüketim',0],['Artan ulaşım',0],['Karbon salınımı artar',1],['Küresel ısınma',1],['Su kirliliği',1]],mis:'u2_neden',e:'Artan üretim, tüketim ve ulaşım nedendir; karbon salınımı, küresel ısınma ve kirlilik bunların sonucudur.'},
  {k:'tf',p:'Küresel çevre sorunları, tek bir ülkenin kendi başına çözebileceği sorunlardır.',a:false,mis:'u2_sinir',e:'Yanlış. Kitaba göre bu sorunlar tüm dünyayı ilgilendirir ve ortak dayanışma gerektirir.'},
  {k:'src',src:{t:'gazete',title:'Yeşil Vatan etkinlikleri başlıyor',by:'Genel ağdan alınan haber (kitapta)',date:'2025-2026',text:'Yeşil Vatan - Benim Okulum Geleceğe Çare etkinlikleri ülkenin her bölgesinde başlıyor. Okulların açıldığı ilk gün film gösterimi ve fidan hediyeleriyle başlayacak yolculuk yıl boyunca şenlik, atölye ve saha çalışmalarıyla sürecek.'},p:'Habere göre bu yolculuk okulların ilk günü nasıl başlayacak?',a:'Film gösterimi ve fidan hediyeleriyle',w:[['Bir futbol turnuvasıyla','u2_kanit'],['Bir sınavla','u2_kanit']],e:'Haberde ilk gün film gösterimi ve fidan hediyeleri olduğu açıkça yazıyor.'},
  {k:'src',src:{t:'afis',title:'Yeşil Vatan anlayışı',by:'Genel ağdan alınan haber (kitapta)',text:'"Yeşil Vatan’ı korumak, vatanı korumaktır!"'},p:'Bu ifade bir kanıt mı, yoksa bir slogan mı?',a:'Bir slogan: bir düşünceyi kısa ve çarpıcı anlatır.',w:[['Bir kanıt: sayı ve ölçüm verir.','u2_kanit'],['Bir tarih: olayın yılını verir.','u2_kavram']],e:'Slogan bir düşünceyi kısa ve çarpıcı biçimde ifade eden sözdür; burada sayı ya da ölçüm yoktur.'},
  {k:'mc',p:'Kitaptaki “yerelden evrensele” ilkesi ne anlatır?',a:'Küresel sorunlara çözüm, bireyin kendi yaşam alanında başlar.',w:[['Küresel sorunları yalnızca başka ülkeler çözer.','u2_sinir'],['Önce dünyayı, sonra evimizi düşünmeliyiz.','u2_neden']],e:'Uluslararası dayanışma gerekse de harekete geçiş noktası bireyin kendi yaşam alanıdır.'},
  {k:'mc',p:'Kitaba göre çevre sorunlarını azaltmanın en temel yolu hangisidir?',a:'Bilinçli üretim, ihtiyaç kadar tüketim ve israfı önlemek',w:[['Daha çok ve gereksiz alışveriş yapmak','u2_neden'],['Sorunu yalnızca gelecek kuşaklara bırakmak','u2_sinir']],e:'Kaynakların doğru kullanıldığı üretim, ihtiyaç kadar almak ve israfı önlemek temel yoldur.'},
  {k:'sc',role:'Okulun “Yeşil Vatan” ekibindesin. Kantinde her gün çok yemek atılıyor, bahçeye de fidan dikilecek.',steps:[
    {p:'Kantinde yemek israfı için ne önerirsin?',o:[['“İhtiyacın kadar al” afişi yapıp sınıflarla konuşuruz',2,'Harika! Bilinçli tüketim ve israfı önlemek çevre sorunlarını azaltmanın temel yoludur.'],['Bu küresel bir sorun, okulumuz bir şey yapamaz',0,'Yerelden evrensele: çözüm kendi yaşam alanımızda başlar.','u2_sinir'],['Sadece ben dikkat ederim',1,'İyi bir başlangıç; ama herkesle birlikte hareket edersen etkisi büyür.']]},
    {p:'Fidanlar dikildi. Sonra ne yaparsınız?',o:[['Sulama ve bakım için sırayla görev alırız',2,'Doğru! Her fidan ve her öğrenci katkısı Yeşil Vatan idealinin parçasıdır.'],['Dikip unuturuz, nasılsa büyür',1,'Dikmek güzel, ama bakılmayan fidan kuruyabilir.'],['Ağaç dikmek bizim işimiz değil',0,'Çevreyi korumak herkesin sorumluluğudur.','u2_sinir']]},
    {p:'Annen markette “Bunu da alalım, indirimde!” diyor ama ihtiyacınız yok. Ne dersin?',o:[['İhtiyacımız olmayanı almayalım derim',2,'Bilinçli tüketim kaynakları korur ve israfı önler.'],['Ne kadar çok alırsak o kadar iyi derim',0,'Aşırı ve gereksiz alışveriş hem israf hem çevre sorunudur.','u2_neden']]}],
   e:'Küresel çevre sorunlarına karşı ilk adım kendi okulumuzda ve evimizde atılır: israfı önlemek, bilinçli tüketmek ve doğaya birlikte sahip çıkmak.'},
  {k:'mc',p:'Kitaba göre kültürel etkileşimle ortaya çıkan sorunlardan biri hangisidir?',a:'Konuşma dilinde bozulmalar ve hazır gıda tüketiminin artması',w:[['Teşhis ve tedavinin kolaylaşması','u2_tekyon'],['Bilgiye ulaşmanın kolaylaşması','u2_tekyon']],e:'Kitap konuşma dilinde bozulma, hazır gıda tüketimi ve gereksiz alışverişi olumsuz etkiler arasında sayar.'},
  {k:'tf',p:'Kitaba göre özgürlük, sorumlulukla birlikte anlam kazanır.',a:true,mis:'u2_kultur',e:'Doğru. Bireyler özgürce seçim yaparken dilini, kültürünü ve değerlerini koruma sorumluluğunu da taşır.'},
  {k:'mc',p:'Kitaba göre medya içeriklerini seçerken nasıl davranmalıyız?',a:'Eleştirel düşünmeliyiz.',w:[['Önümüze çıkan her şeyi izlemeliyiz.','u2_kultur'],['En çok izleneni seçmeliyiz.','u2_kanit']],e:'Kitap, medya içeriklerini seçerken eleştirel düşünmeyi örnek bir sorumluluk olarak verir.'},
  {k:'src',src:{t:'alinti',title:'Kültür Yolu Festivalleri',by:'Ders kitabından (özet)',text:'Kültür Yolu Festivalleri sayesinde geleneksel el sanatlarımız, köklü tarihimiz ve millî musikimiz; modern dijital sergiler, konserler ve tiyatrolarla geniş kitlelere ulaştırılıyor. Gençler kendi kültürel kimliklerini tanıma fırsatı buluyor.'},p:'Bu kaynağa göre festivaller değerlerimizi nasıl yaşatır?',a:'Geleneksel kültürü modern etkinliklerle geniş kitlelere ulaştırarak',w:[['Eski kültürü tamamen bırakıp yerine yenisini koyarak','u2_kultur'],['Yalnızca yabancı müzik türlerini tanıtarak','u2_kultur']],e:'Festivaller geçmişten gelen kültürü dijital sergi, konser ve tiyatroyla bugüne taşır.'},
  {k:'sort',p:'Örnekleri küreselleşmenin değişim başlıklarına yerleştir.',bins:['Kültürel etkileşim','Çevre sorunları','Ticaret'],items:[['Yeni lezzetler tanımak',0],['Popüler müzik yayılır',0],['Karbon salınımı artışı',1],['Ormansızlaşma',1],['Uluslararası şirketler',2],['Başka ülkenin ürünü',2]],mis:'u2_kavram',e:'Kitaptaki şemada değişim; kültürel etkileşim, çevre sorunları, ulaşım-iletişim ve ticaret başlıklarıyla incelenir.'}]});

/* ---------- 2-4 ---------- */
FEN.lesson({id:'2-4',t:'Barış, iş birliği ve ara buluculuk',p:'68–72',kw:'kara sınırı komşuları kültürel iş birliği Ortak Türk Alfabesi yangın Eren yurt dışı yardım Karabağ Kuzey Makedonya Somali Kolombiya barış ara bulucu dış politika',script:[
 ['Görev','Şimdi ikinci konuya geçiyoruz: bölgesel ve küresel sorunların çözümünde ülkemizin rolü. Türkiye komşularıyla ve uzak ülkelerle nasıl iş birliği yapıyor? Barış için neler yapıyor? Haritayı açalım.',[
   ['title','Barış, iş birliği, ara buluculuk','s. 68–72'],['txt','Komşudan dünyaya: iş birliği ve barış',300,' st-cyan']]],
 ['Komşular','Türkiye’nin kara sınırı komşuları Yunanistan, Bulgaristan, Gürcistan, Ermenistan, Azerbaycan, İran, Irak ve Suriye’dir. Türkiye komşularıyla kültür, sanat ve spor alanlarında iş birliği yapar.',[
   ['map','dunya',[['country','GRC','Yunanistan'],['country','BGR','Bulgaristan'],['country','GEO','Gürcistan'],['country','ARM','Ermenistan'],['country','AZE','Azerbaycan'],['country','IRN','İran'],['country','IRQ','Irak'],['country','SYR','Suriye']]]]],
 ['Kültür köprüleri','İki bin yirmi dört yılında Türk ve Yunan sanatçılar birlikte bir tiyatro oyunu sahneledi. Türk ve Ermeni millî takımları resmî futbol maçları yaptı. Türk Devletleri Teşkilatı toplantılarında otuz dört harfli Ortak Türk Alfabesi oy birliğiyle kabul edildi.',[
   ['cards',[['🎭','Ortak tiyatro','Türk ve Yunan sanatçılar'],['⚽','Futbol maçları','Türk ve Ermeni takımları'],['🔤','Ortak Türk Alfabesi','34 harf, oy birliği']]]]],
 ['Eren','Eren ailesiyle pikniğe gitti. Söndürülmeden bırakılan bir ateş kuru otları tutuşturdu. Herkes iş birliği yaptı, itfaiye ve AFAD geldi. Yangın büyüyünce Türkiye başka ülkelerden uçak ve ekipman desteği aldı; Azerbaycan’dan gelen ekipler de yardım etti. Ülkeler de insanlar gibi zor zamanda dayanışır.',[
   ['chain',[['🔥','Söndürülmemiş ateş'],['🌾','Kuru otlar tutuştu'],['🤝','Herkes yardım etti'],['🚒','İtfaiye ve AFAD'],['✈️','Ülkelerden destek']],170],
   ['tip','Tek başına çözülmeyen sorun, birlikte çözülür.']]],
 ['Yardım haritası','Türkiye birçok ülkeye yardım eder. Karabağ’da Ağdam ve Zengilan’daki hastanelerin donanımını karşıladı. Kuzey Makedonya’da Kalkandelen Maarif Okulu bin iki yüz öğrenciye hizmet veriyor. Somali’deki hastane iki bin on beşten beri çalışıyor. Kolombiya’da Türk yazarların kitapları mobil kütüphaneyle halka ulaştı.',[
   ['map','dunya',[['country','AZE','Karabağ: hastane'],['country','MKD','Okul'],['country','SOM','Hastane'],['country','TUR','Türkiye']]],
   ['timeline',[[2015,'Somali’de hastane'],[2017,'Üsküp’te faaliyet'],[2022,'Kalkandelen okulu']]]]],
 ['Ara bulucu','Barış, insanların ve toplumların karşılıklı saygı, güven ve anlayışla çatışmadan bir arada yaşamasıdır. Türkiye girişimci ve insani bir dış politika izler: mazlumlara yardım eder, çözüm üretir, ara buluculuk yapar. İki bin yirmi beşte birçok krizde ara bulucu oldu.',[
   ['source',{t:'gazete',title:'Ara bulucu ülke: Türkiye',by:'Genel ağdan alınan haber (kitapta)',date:'2025',text:'Türk diplomasisi 2025 yılını yoğun geçirdi. Türkiye birçok krizde ara bulucu oldu ve tarafların bir araya gelmesi için ev sahipliği yaptı. Rusya–Ukrayna Savaşı’nda taraflarla iletişim kurabilen nadir ülkelerden biriydi.'},['ara bulucu','ev sahipliği']],
   ['map','dunya',[['country','UKR','Ukrayna'],['country','ETH','Etiyopya'],['country','SOM','Somali'],['country','SDN','Sudan'],['country','BIH','Bosna Hersek']]]]],
 ['Tuzak','Dikkat! Ara bulucu, taraflardan birinin yanında yer alan kişi değildir. Ara bulucu, anlaşmazlığı çözmek için taraflar arasında iletişimi ve uzlaşmayı sağlar.',[
   ['trap','Ara bulucu, haklı gördüğü tarafı tutar.'],['txt','Ara bulucu: iletişim ve uzlaşmayı sağlar.',330,' st-ok']]],
 ['Özet','Özetleyelim. Türkiye komşularıyla kültür, sanat ve sporda iş birliği yapar. Farklı kıtalarda sağlık, eğitim ve kültür alanında yardım eder. Barışı önemser; sorunların uzlaşmayla çözülmesi için ara buluculuk yapar. Yurtta sulh, cihanda sulh.',[
   ['rules',['Komşularla kültür, sanat, spor iş birliği','Yardımlar: sağlık, eğitim, kültür alanında','Barış: saygı, güven, anlayışla bir arada yaşamak','Dış politika: girişimci ve insani','Ara bulucu taraf tutmaz, uzlaşma sağlar'],150]]]],
 q:[
  {k:'map',map:'dunya',p:'2024 yılında Türk sanatçılarla birlikte tiyatro oyunu sahneleyen sanatçıların ülkesini haritada bul.',a:'GRC',w:['BGR','ITA','CYP'],mis:'u2_yon',e:'Kitapta Türk ve Yunan sanatçıların birlikte tiyatro sahnelediği anlatılır; Yunanistan batı komşumuzdur.'},
  {k:'map',map:'dunya',p:'Ağdam ve Zengilan’daki hastanelerin donanımını Türkiye karşıladı. Karabağ’ın bulunduğu ülkeyi haritada bul.',a:'AZE',w:['ARM','GEO','IRN'],mis:'u2_yon',e:'Karabağ Azerbaycan’dadır; Azerbaycan Türkiye’nin doğusunda, Hazar Denizi kıyısındadır.'},
  {k:'map',map:'dunya',p:'Uluslararası Kalkandelen Maarif Okulu’nun bulunduğu ülkeyi haritada bul.',a:'MKD',w:['ALB','SRB','BGR'],mis:'u2_yon',e:'Okul Kuzey Makedonya’dadır; Türkiye 2017’den beri Üsküp’te faaliyet gösteriyor.'},
  {k:'map',map:'dunya',p:'Türkiye’nin yaptırdığı Eğitim ve Araştırma Hastanesi’nin 2015’ten beri hizmet verdiği ülkeyi haritada bul.',a:'SOM',w:['ETH','SDN','YEM'],mis:'u2_yon',e:'Hastane Somali’dedir; Somali Afrika’nın doğu ucundadır.'},
  {k:'src',src:{t:'gazete',title:'Ortak Türk Alfabesi kabul edildi',by:'Ders kitabındaki bilgi kutusu',text:'Türk Devletleri Teşkilatı bünyesinde düzenlenen toplantılarda 34 harften oluşan “Ortak Türk Alfabesi” oy birliğiyle kabul edildi.'},p:'Bu kaynağa göre Ortak Türk Alfabesi nasıl kabul edildi?',a:'Türk Devletleri Teşkilatı toplantılarında oy birliğiyle',w:[['Tek bir ülkenin kararıyla','u2_kanit'],['Oy çokluğuyla, bazı ülkeler karşı çıkarak','u2_kanit']],e:'Kaynakta alfabenin 34 harfli olduğu ve oy birliğiyle kabul edildiği yazar.'},
  {k:'src',src:{t:'gazete',title:'Kolombiya’da mobil kütüphane',by:'Ders kitabındaki bilgi kutusu',text:'İspanyolcaya çevrilen Türk yazarların eserleri, başkent Bogota’da kitaba ve kütüphaneye ulaşmakta zorlanan insanlar için mobil kütüphaneyle buluşturuldu. Böylece iki ülke arasında bir gönül köprüsü kuruldu.'},p:'Bu kaynağa göre bu uygulamanın amacı nedir?',a:'Kitaba ulaşamayanlara kitap götürmek ve gönül köprüsü kurmak',w:[['Türkiye’ye kitap satmak','u2_kanit'],['Kolombiya’da Türkçe sınavı yapmak','u2_kanit']],e:'Kaynak, kitaba erişmekte zorlananlara yönelik bir uygulama olduğunu ve iki ülke arasında gönül köprüsü kurduğunu söyler.'},
  {k:'src',src:{t:'tablo',title:'Türkiye’nin bazı yurt dışı çalışmaları',by:'Ders kitabındaki bilgi görselinden',rows:[['Yer','Alan','Örnek'],['Karabağ','Sağlık','Hastane donanımı'],['Kuzey Makedonya','Eğitim','Maarif Okulu'],['Kolombiya','Kültür','Mobil kütüphane'],['Somali','Sağlık','Hastane']]},p:'Tabloya göre hangisi söylenebilir?',a:'Türkiye farklı kıtalarda, farklı alanlarda yardım yapmaktadır.',w:[['Türkiye yalnızca komşularına yardım etmektedir.','u2_kanit'],['Türkiye yalnızca eğitim alanında yardım etmektedir.','u2_kanit']],e:'Tabloda Avrupa, Asya, Afrika ve Güney Amerika’dan örnekler ile sağlık, eğitim ve kültür alanları var.'},
  {k:'tl',p:'Olayları zaman tünelinde sırala.',ev:[[2015,'Somali’de hastane açıldı'],[2017,'Üsküp’te çalışma başladı'],[2022,'Kalkandelen okulu açıldı'],[2024,'Türk-Yunan tiyatrosu'],[2025,'Yoğun diplomasi yılı']],mis:'u2_tarih',e:'2015 Somali, 2017 Üsküp, 2022 Kalkandelen okulu, 2024 ortak tiyatro, 2025 yoğun diplomasi yılı.'},
  {k:'mc',p:'Eren’in öyküsünde mesire alanındaki insanların yangına birlikte müdahale etmesi hangi değerin önemini gösterir?',a:'İş birliği ve dayanışma',w:[['Yarışma ve rekabet','u2_kavram'],['Tek başına hareket etme','u2_sinir']],e:'İnsanlar su şişeleri, toprak ve dallarla birlikte çalışarak yangının büyümesini engellemeye çalıştı.'},
  {k:'mc',p:'Eren’in yaşadığı olay ile ülkelerin küresel sorunlara birlikte çözüm araması arasındaki benzerlik nedir?',a:'Tek başına çözülemeyen sorunlar dayanışmayla çözülür.',w:[['Her ülke kendi sorununu yalnız çözmelidir.','u2_sinir'],['Yangınlar yalnızca bir ülkeyi ilgilendirir.','u2_sinir']],e:'Yangın büyüyünce başka ülkelerden destek alındı; ülkeler de afet ve savaş gibi sorunlarda dayanışır.'},
  {k:'order',p:'Eren’in öyküsündeki olayları sırala.',items:['Ateş söndürülmeden kaldı','Kuru otlar tutuştu','Halk müdahale etti','İtfaiye ve AFAD geldi','Ülkeler destek verdi'],mis:'u2_neden',e:'Küçük bir dikkatsizlik büyük bir yangına dönüştü; önce halk, sonra ekipler, en sonunda da başka ülkeler yardıma geldi.'},
  {k:'mc',p:'Eren’in öyküsünde Türk ekipleriyle birlikte yangını söndürmeye yardım eden ekipler hangi ülkeden geldi?',a:'Azerbaycan',w:[['Kolombiya','u2_kanit'],['Somali','u2_kanit']],e:'Öyküde Azerbaycan’dan gelen ekiplerin Türk ekipleriyle birlikte çalıştığı anlatılır.'},
  {k:'mc',p:'Kitaba göre barış nedir?',a:'Toplumların saygı, güven ve anlayışla çatışmadan bir arada yaşaması',w:[['Güçlü olanın her zaman kazanması','u2_kavram'],['Ülkelerin birbirleriyle hiç konuşmaması','u2_kavram']],e:'Barış, karşılıklı saygı, güven ve anlayış içinde çatışmadan bir arada yaşamaktır.'},
  {k:'tf',p:'Kitaba göre dünya barışının sürmesi için tüm ülkelerin uluslararası hukuk kurallarına uygun davranması gerekir.',a:true,mis:'u2_kavram',e:'Doğru. Kitap bunu dünya barışının sürdürülebilmesi için gerekli sayar.'},
  {k:'mc',p:'Türkiye’nin “girişimci ve insani dış politika” anlayışı neyi esas alır?',a:'Mazlumlara yardımı, çözüm üretmeyi ve ara buluculuğu',w:[['Sorunları görmezden gelmeyi','u2_kavram'],['Yalnızca kendi ticaretini düşünmeyi','u2_kavram']],e:'Bu anlayış mazlumlara yardım etmeyi, sorunlara çözüm üretmeyi ve çatışmaları bitirmek için ara buluculuğu esas alır.'},
  {k:'tf',p:'Ara bulucu, anlaşmazlıkta haklı gördüğü tarafın yanında yer alan kişidir.',a:false,mis:'u2_kavram',e:'Yanlış. Ara bulucu, taraflar arasındaki anlaşmazlığı çözmek için iletişimi ve uzlaşmayı sağlar.'},
  {k:'src',src:{t:'gazete',title:'Ara bulucu ülke: Türkiye',by:'Genel ağdan alınan haber (kitapta)',date:'2025',text:'Türkiye 2025’te birçok krizde ara bulucu oldu ve taraflara ev sahipliği yaptı. Gazze’deki ateşkes sürecinde rol oynadı; Etiyopya ile Somali, Sudan ile Birleşik Arap Emirlikleri arasındaki sorunların çözümünde de görev aldı.'},p:'Bu habere göre Türkiye 2025’te uluslararası alanda hangi rolü üstlendi?',a:'Ara bulucu ve ev sahibi ülke rolünü',w:[['Savaşan taraflardan biri olma rolünü','u2_kavram'],['Krizlerden tamamen uzak durma rolünü','u2_kanit']],e:'Haber, Türkiye’nin hem ara bulucu olduğunu hem de tarafların buluşması için ev sahipliği yaptığını anlatır.'},
  {k:'map',map:'dunya',p:'2025’te Türkiye, Somali ile hangi ülke arasındaki sorunun çözümünde ara bulucu oldu? O ülkeyi haritada bul.',a:'ETH',w:['SDN','YEM','EGY'],mis:'u2_yon',e:'Haberde Etiyopya ile Somali arasındaki sorun geçer; Etiyopya, Somali’nin batı komşusudur.'},
  {k:'mc',p:'Kitaba göre savaşlar toplumları nasıl etkiler?',a:'Can ve mal güvenliğini tehdit eder, büyük yıkımlara yol açar.',w:[['Toplumların düzenini güçlendirir.','u2_neden'],['Şehirlerin gelişmesini hızlandırır.','u2_neden']],e:'Savaşlarda insanlar ölür, şehirler zarar görür; bu yüzden sorunları barışçıl yollarla çözmek önemlidir.'},
  {k:'sc',role:'Barışı seven bir ülkenin genç diplomatısın. İki komşu ülke, aralarındaki bir su kaynağı yüzünden anlaşmazlık yaşıyor.',steps:[
    {p:'İki ülke de birbirine kızgın. İlk ne yaparsın?',o:[['İki tarafla da konuşup ikisini de dinlerim',2,'Doğru! Ara bulucu iletişimi sağlar; taraflarla konuşabilmek ilk adımdır.'],['Hemen birini haklı ilan ederim',0,'Ara bulucu taraf tutmaz; yoksa güveni kaybeder.','u2_kavram'],['Bizi ilgilendirmez, beklerim',1,'Beklemek kavgayı büyütebilir; girişimci dış politika çözüm üretmeyi esas alır.']]},
    {p:'İki taraf da konuşmayı kabul etti. Ne önerirsin?',o:[['Ülkemde ortak bir görüşme masası kurarım',2,'Harika! Türkiye de tarafları bir araya getirmek için ev sahipliği yapar.'],['Sorunu silahla çözmelerini söylerim',0,'Savaş büyük yıkımlar getirir; sorunlar uzlaşmayla çözülmelidir.','u2_neden']]},
    {p:'Anlaşma imzalandı. Barışı güçlendirmek için ne yaparsın?',o:[['Ortak sanat ve spor etkinlikleri öneririm',2,'Kültür, sanat ve spor iş birliği toplumları birbirine yaklaştırır.'],['Hiçbir şey yapmam, iş bitti',1,'Anlaşma iyi; ama dostça ilişkiler kurmak barışı kalıcı yapar.']]}],
   e:'Barış için ara bulucu iki tarafı da dinler, taraf tutmaz, uzlaşma masası kurar ve dostça ilişkileri kültür, sanat, sporla güçlendirir.'}]});

/* ---------- 2-5 ---------- */
FEN.lesson({id:'2-5',t:'Göç, iklim krizi ve insani yardım',p:'73–83',kw:'göç mülteci Ahıska Türkleri Suriyeli iklim krizi COP31 2053 sıfır emisyon insani yardım TİKA AFAD Türk Kızılay İyilik Gemisi tahıl anlaşması empati',script:[
 ['Görev','Son görevimiz: göç, mülteciler, iklim krizi ve insani yardım. Türkiye bu küresel sorunlarda ne yapıyor? Sen olsan ne yapardın? Hadi keşfedelim.',[
   ['title','Göç, iklim, insani yardım','s. 73–83'],['cards',[['🧳','Göç','Daha iyi yaşam arayışı'],['⛺','Mülteciler','Savaştan kaçanlar'],['🌡️','İklim krizi','Ortak sorumluluk'],['📦','İnsani yardım','Temel ihtiyaç desteği']]]]],
 ['Göç ve mülteci','Göç, insanların güvenli bir ortamda ya da daha iyi koşullarda yaşamak için yaşadıkları yerden başka bir yere taşınmasıdır. Mülteciler ise savaş, çatışma veya baskı yüzünden ülkesini terk etmek zorunda kalan insanlardır. İki kavramı karıştırmayalım.',[
   ['compare',['Göç','Mülteci'],[['Yer değiştirme','Ülkesini terke zorunlu'],['Güvenlik ya da iyi yaşam','Savaş, çatışma, baskı'],['Uyum ve anlayış gerekir','Temel ihtiyaç bile zor']]]]],
 ['Türkiye ve göç','Yirmi altı Kasım iki bin yirmi beş itibarıyla Türkiye’de yasal olarak bulunan yabancı sayısı üç milyon altı yüz on bir bin iki yüz on sekizdir. Türkiye göçü insan hakları, aile bütünlüğü ve toplumsal uyum çerçevesinde yönetir. Ahıska Türkü soydaşlarımız için Bitlis’te konutlar yapıldı.',[
   ['txt','Yasal yabancı sayısı: 3 611 218 (26 Kasım 2025)',110,' st-gold'],
   ['source',{t:'gazete',title:'Ahıska Türkleri için konutlar',by:'Genel ağdan alınan haber (kitapta)',text:'Göç İdaresi Başkanlığınca Ahıska Türkü soydaşlarımız için Bitlis’te yapılan TOKİ konutları incelendi. Toplantıda tarım, sanayi, hayvancılık ve istihdam ile eğitim, sağlık ve sosyal hizmetlere erişim planları ele alındı.'},['tarım, sanayi, hayvancılık','eğitim, sağlık']]]],
 ['İklim krizi','İklim krizi; fosil yakıtların yoğun kullanılması, ormanların kesilmesi ve sanayileşmenin artmasıyla atmosfere fazla sera gazı salınması sonucu ortaya çıkar. Sıcaklıklar artar, kuraklık, sel ve başka afetler çoğalır. Bu sorun tüm dünyayı etkiler, çözümü ortak sorumluluk ister.',[
   ['chain',[['⛽','Fosil yakıt'],['🪓','Orman kesimi'],['🏭','Sanayileşme'],['💨','Fazla sera gazı'],['🌡️','Kuraklık, sel']],170],
   ['source',{t:'alinti',title:'Dünya ortak evimiz',by:'Çevre ve İklim Değişikliği Bakanlığı',text:'Kadim dünyadan bugüne ulaşan tek bir reçete vardır: Doğayla uyumlu yaşamak. Çünkü dünya ortak evimizdir ve bizim gideceğimiz başka bir yer yoktur.'},['Doğayla uyumlu yaşamak','dünya ortak evimizdir']]]],
 ['İnsani yardım','İnsani yardım; afet, savaş ve yoksullukta insanların temel ihtiyaçlarını karşılamak için yapılan destektir. Türkiye; Gazze, Suriye, Yemen, Arakan ve Afrika’daki krizlerde en erken yardım ulaştıran ülkelerdendir. TİKA, AFAD ve Türk Kızılay gıda, ilaç, çadır, temiz su ve sağlık hizmeti ulaştırır.',[
   ['map','dunya',[['country','TUR','Türkiye'],['country','SYR','Suriye'],['country','YEM','Yemen'],['country','EGY','Mısır: El Ariş'],['country','SOM','Somali']]],
   ['cards',[['🌙','Türk Kızılay','İyilik Gemileri'],['🚨','AFAD','Afet ve acil durum'],['🤝','TİKA','İş birliği ve kalkınma']]]]],
 ['Diplomasi','Rusya ile Ukrayna arasındaki savaş sürerken Türkiye tarafsız kaldı ve barış görüşmelerine ev sahipliği yaptı. Türkiye’nin ara buluculuğuyla Karadeniz’de tahıl trafiğini düzenleyen ilk anlaşma İstanbul’da imzalandı. Türk Kızılay ise iki bin yirmi üçten beri İyilik Gemileriyle Gazze’ye yardım taşıyor.',[
   ['map','dunya',[['country','RUS','Rusya'],['country','UKR','Ukrayna'],['country','TUR','İstanbul anlaşması']]],
   ['timeline',[[2015,'Somali’de hastane'],[2023,'İyilik Gemileri'],[2025,'Ara buluculuk yılı'],[2053,'Sıfır emisyon hedefi']]]]],
 ['Tuzak','Dikkat! Kitaptaki bir test sorusu bunu sorar: Sorunları askerî yöntemlerle hızlıca çözmek Türkiye’nin yolu değildir. Türkiye diplomasiye önem verir ve sorunların barışçıl yollarla çözülmesine katkı sağlar. Tek başına bekle-gör politikası da izlemez; uluslararası iş birliğini güçlendirir.',[
   ['trap','Sorunlar en hızlı askerî yolla çözülür.'],
   ['lines',['Diplomasi ve barışçıl çözüm','İnsani yardım ve mültecilere destek','Afetlerde hızlı yardım','Uluslararası iş birliği ve dayanışma'],200]]],
 ['Özet','Özetleyelim. Türkiye göçü insan haklarıyla yönetir, mültecilere kucak açar. İklim krizine karşı iki bin elli üç sıfır emisyon hedefiyle çalışır. Beş kıtada insani yardım yapar ve ara buluculukla barışa katkı sağlar. Bütün bunların temelinde yardımseverlik, dayanışma, fedakârlık ve empati vardır.',[
   ['rules',['Göç ≠ mülteci: zorunlu kaçış mültecidir','Göç: insan hakları, aile, toplumsal uyum','İklim: 2053 Sıfır Emisyon Hedefi','Yardım: TİKA, AFAD, Türk Kızılay, beş kıta','Temel değerler: dayanışma, fedakârlık, empati'],150]]]],
 q:[
  {k:'mc',p:'Kitaba göre göç nedir?',a:'Güvenli ya da daha iyi koşullarda yaşamak için başka yere taşınmak',w:[['Bir ülkenin başka ülkeye yardım göndermesi','u2_kavram'],['Bir şehirde kısa bir gezi yapmak','u2_kavram']],e:'Göç, güvenli bir ortam ya da daha iyi yaşam koşulları için yaşanan yerden başka bir yere taşınmaktır.'},
  {k:'mc',p:'Hangisi mülteci kavramını doğru anlatır?',a:'Savaş, çatışma ya da baskı yüzünden ülkesini terke zorlanan kişi',w:[['Tatil için başka ülkeye giden kişi','u2_kavram'],['Başka ülkede ticaret yapan şirket','u2_kavram']],e:'Mülteci, zorunlu olarak ülkesini terk edip başka ülkeye sığınan kişidir.'},
  {k:'mc',p:'Kitaba göre Türkiye göçü hangi yaklaşımla yönetir?',a:'İnsan hakları, aile bütünlüğü ve toplumsal uyum çerçevesinde',w:[['Yalnızca güvenlik amacıyla','u2_kanit'],['Göçmenleri hiç kabul etmeyerek','u2_kanit']],e:'Kitap Türkiye’nin göçü yalnızca güvenlik amaçlı değil, bütüncül bir yaklaşımla yönettiğini söyler.'},
  {k:'src',src:{t:'gazete',title:'Ahıska Türkleri için konutlar',by:'Genel ağdan alınan haber (kitapta)',text:'Bitlis Valiliğinin toplantısında konutların tamamlanma takvimi; tarım, sanayi ve hayvancılık faaliyetleri ile yeni istihdam alanları; eğitim, sağlık ve sosyal hizmetlere erişim ele alındı.'},p:'Bu habere göre Ahıska Türklerinin uyumu için hangi alanlarda çalışma yapılıyor?',a:'Konut, iş ve istihdam, eğitim, sağlık ve sosyal hizmet',w:[['Yalnızca spor ve eğlence','u2_kanit'],['Yalnızca turizm','u2_kanit']],e:'Haberde konut, tarım-sanayi-hayvancılık, istihdam, eğitim, sağlık ve sosyal hizmetler sayılır.'},
  {k:'src',src:{t:'gazete',title:'Suriyeli Ahmet’in veda mektubu',by:'Genel ağdan alınan haber (kitapta)',text:'Ailesi yaklaşık 10 yıldır Türkiye’de yaşayan Suriyeli Ahmet, ülkesine dönerken ilkokuldaki arkadaşlarına ve öğretmenlerine, annesinin yazdığı duygu yüklü ve teşekkür dolu bir mektupla veda etti.'},p:'Bu habere göre Ahmet’in ailesi Türkiye’ye karşı hangi duyguyu öne çıkarıyor?',a:'Teşekkür ve minnet',w:[['Öfke ve kırgınlık','u2_kanit'],['İlgisizlik','u2_kanit']],e:'Mektubun duygu yüklü ve teşekkür dolu olduğu haberde açıkça yazıyor.'},
  {k:'mc',p:'Kitaba göre Türkiye, millî gelirine oranlandığında insani ve kalkınma yardımlarında hangi unvanı taşır?',a:'Dünyanın en cömert ülkesi',w:[['Dünyanın en kalabalık ülkesi','u2_kavram'],['Dünyanın en büyük ihracatçısı','u2_kavram']],e:'Beş kıtadaki yardımları millî gelirine oranlandığında Türkiye dünyanın en cömert ülkesi unvanını taşır.'},
  {k:'sort',p:'İklim kriziyle ilgili örnekleri neden ve sonuç diye ayır.',bins:['Neden','Sonuç'],items:[['Fosil yakıt kullanımı',0],['Ormanların kesilmesi',0],['Sanayileşmenin artması',0],['Sıcaklıkların artması',1],['Kuraklık',1],['Sel ve afetler',1]],mis:'u2_neden',e:'Fosil yakıt, orman kesimi ve sanayileşme sera gazını artırır; sonuçta sıcaklık artar, kuraklık ve seller çoğalır.'},
  {k:'tf',p:'İklim krizi yalnızca bir ülkeyi etkileyen yerel bir sorundur.',a:false,mis:'u2_sinir',e:'Yanlış. Kitaba göre iklim krizi tüm dünyayı etkiler; çözümü için bütün ülkeler birlikte hareket etmelidir.'},
  {k:'src',src:{t:'gazete',title:'Amman’da iklim çalıştayı',by:'Genel ağdan alınan haber (kitapta)',text:'Türkiye’nin Amman Büyükelçisi, iklim değişikliğinin küresel ölçekte etkili olduğunu ve nesillerin geleceğinin tehdit altında olduğunu söyledi. Türkiye’nin "Yeşil Dönüşüm Vizyonu" ve "2053 Sıfır Emisyon Hedefi" doğrultusunda çalıştığı belirtildi.'},p:'Bu habere göre Türkiye iklim değişikliğine karşı hangi hedefle çalışıyor?',a:'2053 Sıfır Emisyon Hedefi ve Yeşil Dönüşüm Vizyonu',w:[['Daha çok fosil yakıt kullanma hedefi','u2_kanit'],['Ormanları azaltma hedefi','u2_neden']],e:'Haberde iki hedef açıkça yazıyor: Yeşil Dönüşüm Vizyonu ve 2053 Sıfır Emisyon Hedefi.'},
  {k:'map',map:'dunya',p:'Türkiye’nin Amman Büyükelçisinin konuştuğu iklim konferansının yapıldığı ülkeyi haritada bul.',a:'JOR',w:['SYR','IRQ','SAU'],mis:'u2_yon',e:'Amman, Ürdün’ün başkentidir; Ürdün Suriye’nin güneyindedir.'},
  {k:'src',src:{t:'alinti',title:'Dünya ortak evimiz',by:'Çevre ve İklim Değişikliği Bakanlığı',text:'"Kadim dünyadan bugüne ulaşan tek bir reçete vardır: Doğayla uyumlu yaşamak. Çünkü dünya ortak evimizdir ve bizim gideceğimiz başka bir yer yoktur."'},p:'Bu sözle hangi düşünce vurgulanıyor?',a:'Dünyayı korumak hepimizin ortak sorumluluğudur.',w:[['Doğa yalnızca bilim insanlarını ilgilendirir.','u2_sinir'],['Gerekirse başka bir gezegene taşınırız.','u2_kanit']],e:'“Dünya ortak evimizdir” sözü, iklim krizine karşı ortak sorumluluğu ve doğayla uyumlu yaşamayı vurgular.'},
  {k:'mc',p:'Kitaba göre insani yardım nedir?',a:'Afet, savaş, yoksullukta temel ihtiyaçlar için yapılan destek',w:[['Ülkeler arasında yapılan futbol maçı','u2_kavram'],['Başka ülkeye ürün satarak para kazanmak','u2_kavram']],e:'İnsani yardım; gıda, sağlık, barınma ve eğitim gibi temel ihtiyaçlar için yapılan destektir.'},
  {k:'mc',p:'Kitaba göre Türkiye’nin insani yardımları hangi kurumlar aracılığıyla ulaştırılır?',a:'TİKA, AFAD ve Türk Kızılay',w:[['Türkiye İhracatçılar Meclisi','u2_kavram'],['Yalnızca büyük uluslararası şirketler','u2_kavram']],e:'Kitap yardımların TİKA, AFAD ve Türk Kızılay gibi kurumlar aracılığıyla ulaştırıldığını söyler.'},
  {k:'src',src:{t:'gazete',title:'21. İyilik Gemisi Mısır’a ulaştı',by:'Genel ağdan alınan haber (kitapta)',text:'Türk Kızılayın Gazze için hazırladığı 21. İyilik Gemisi, Mısır’ın El Ariş Limanı’na ulaştı. Yaklaşık 3 bin 300 ton yardım taşıyan gemide 175 bin gıda kolisinin yanında hijyen, giyim, barınma ve su malzemeleri var.'},p:'Bu habere göre İyilik Gemisi hangi tür yardımları taşıyor?',a:'Gıda, hijyen, giyim, barınma ve su malzemeleri',w:[['Yalnızca oyuncak ve kitap','u2_kanit'],['Yalnızca inşaat malzemesi','u2_kanit']],e:'Haberde gıda kolileri ile hijyen, giyim, barınma ve su malzemeleri sayılır; bunlar temel ihtiyaçlardır.'},
  {k:'map',map:'dunya',p:'Gazze’ye gönderilen 21. İyilik Gemisi’nin ulaştığı El Ariş Limanı hangi ülkededir? Haritada bul.',a:'EGY',w:['LBY','JOR','SAU'],mis:'u2_yon',e:'El Ariş Limanı Mısır’dadır; yardımlar oradan Gazze’ye ulaştırılır.'},
  {k:'src',src:{t:'belge',title:'Kaynak A: Tahıl anlaşması',by:'Genel ağdan alınan metin (kitapta)',text:'Türkiye’nin ara buluculuğu ve BM Genel Sekreterinin katılımıyla, Karadeniz’de tahıl trafiğini düzenleyen ilk anlaşma İstanbul’da imzalandı. Anlaşma, savaş hâlindeki Rusya ve Ukrayna’nın savunma bakanlarını aynı masada buluşturdu.'},p:'Bu kaynağa göre anlaşma neden dünyada büyük yankı uyandırdı?',a:'Savaşan iki ülkenin bakanlarını aynı masada buluşturduğu için',w:[['Savaşı askerî yolla bitirdiği için','u2_kavram'],['Yalnızca Türkiye’nin ticaretini ilgilendirdiği için','u2_sinir']],e:'Kaynak, sıcak savaştaki iki ülkenin savunma bakanlarının aynı masaya oturmasının büyük bir diplomasi başarısı olduğunu söyler.'},
  {k:'tl',p:'Olayları zaman tünelinde sırala.',ev:[[2015,'Somali’de hastane açıldı'],[2023,'İyilik Gemileri başladı'],[2025,'3,6 milyon yasal yabancı'],[2053,'Sıfır emisyon hedefi']],mis:'u2_tarih',e:'2015 Somali hastanesi, 2023 İyilik Gemileri, 2025 yabancı sayısı; 2053 ise ulaşılmak istenen bir hedeftir.'},
  {k:'mc',p:'Kitaba göre insanlarda yardım etme isteğini güçlendiren en temel duygu hangisidir?',a:'Empati',w:[['Rekabet','u2_kavram'],['Kıskançlık','u2_kavram']],e:'Empati, karşındakinin ne hissettiğini anlamaya çalışmaktır; insanı sorunlara karşı duyarlı yapar.'},
  {k:'mc',p:'Hangisi Türkiye’nin uluslararası alanda yürüttüğü çalışmalar arasında yer almaz?',a:'Sorunları askerî yöntemlerle hızlıca çözmek',w:[['Sorunların çözümünde diplomasiye önem vermek','u2_kavram'],['Mültecilere destek olmak','u2_kavram'],['Afetlerde ihtiyaç sahiplerine yardım etmek','u2_kavram']],e:'Kitaba göre Türkiye diplomasiye önem verir ve sorunların barışçıl yollarla çözülmesine katkı sağlar.'},
  {k:'tf',p:'Türkiye sorunların çözümünde tek başına hareket eder ve bekle-gör politikası izler.',a:false,mis:'u2_sinir',e:'Yanlış. Türkiye küresel sorunlarda uluslararası iş birliğini güçlendirir ve etkin, yapıcı bir tutum sergiler.'},
  {k:'mc',p:'Kitaba göre Türkiye’nin hem fiziki hem uluslararası ilişkiler açısından önemini artıran özellik hangisidir?',a:'Doğu ile Batı arasında bir köprü görevi görmesi',w:[['Hiçbir ülkeyle ilişki kurmaması','u2_kavram'],['Yalnızca kendi bölgesiyle ilgilenmesi','u2_sinir']],e:'Stratejik konumu ve Doğu ile Batı arasındaki köprü rolü Türkiye’nin önemini artırır.'},
  {k:'sc',role:'Okulunda etkin bir öğrencisin. Afetten etkilenen ailelere yardım için bir faaliyet düzenleyeceksin.',steps:[
    {p:'İşe nereden başlarsın?',o:[['Adını, amacını, yerini, süresini, sorumlusunu planlarım',2,'Harika! Kitaptaki Sevcan örneği de önce plan yapmayı ister.'],['Plan yapmadan herkesten bir şeyler toplarım',1,'İyi niyetli; ama plansız yardım ihtiyaca tam ulaşmayabilir.'],['Uzaktaki bir afet bizi ilgilendirmez derim',0,'Empati ve dayanışma, uzaktaki insanların sorununu da önemsemeyi gerektirir.','u2_sinir']]},
    {p:'Ne toplayacağınıza nasıl karar verirsiniz?',o:[['İhtiyaç listesini yardım kuruluşundan öğreniriz',2,'Doğru! İnsani yardım temel ihtiyaçları karşılamak içindir: gıda, temiz su, giyim, barınma.'],['Evdeki kırık, kullanılmaz eşyaları getiririz',0,'İnsani yardım temel ihtiyaca yönelik olmalıdır; kullanılmaz eşya işe yaramaz.','u2_kavram']]},
    {p:'Toplanan yardımları nasıl ulaştırırsınız?',o:[['Türk Kızılay ya da AFAD gibi güvenilir bir kurumla',2,'Bu kurumlar yardımları ihtiyaç sahiplerine düzenli ve güvenli şekilde ulaştırır.'],['Sosyal medyada tanımadığımız birine veririz',0,'Kaynağı belli olmayan kişilere güvenmek yardımın boşa gitmesine yol açabilir.','u2_kanit'],['Okulda bekletiriz, sonra bakarız',1,'Afetlerde hız önemlidir; yardım bekletilmemelidir.']]}],
   e:'İyi bir yardım faaliyeti plan ister, gerçek ihtiyaca göre yapılır ve güvenilir kurumlarla ulaştırılır. Temelinde empati ve dayanışma vardır.'}]});
